package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId WARSAW = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FMT = DateTimeFormatter.ofPattern("uuuu-MM-dd").withResolverStyle(ResolverStyle.STRICT);
    private static final DateTimeFormatter INSTANT_FMT = DateTimeFormatter.ISO_OFFSET_DATE_TIME;
    private static final Set<MonthDay> HOLIDAYS = Set.of(
        MonthDay.of(1, 1), MonthDay.of(1, 6), MonthDay.of(5, 1), MonthDay.of(5, 3),
        MonthDay.of(8, 15), MonthDay.of(11, 1), MonthDay.of(11, 11), MonthDay.of(12, 25), MonthDay.of(12, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        return isBusinessDay(parseDate(date));
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = ZonedDateTime.parse(submittedAt, INSTANT_FMT).withZoneSameInstant(WARSAW);
        LocalDate date = zdt.toLocalDate();
        LocalTime time = zdt.toLocalTime();
        boolean afterCutoff = time.isAfter(LocalTime.of(16, 0));

        if (!isBusinessDay(date) || afterCutoff) {
            date = nextBusinessDay(date);
        }
        return date.format(DATE_FMT);
    }

    @Override
    public String settlementDate(String submittedAt) {
        ZonedDateTime zdt = ZonedDateTime.parse(submittedAt, INSTANT_FMT).withZoneSameInstant(WARSAW);
        LocalDate proc = LocalDate.parse(processingDate(submittedAt), DATE_FMT);
        return nextBusinessDay(proc).format(DATE_FMT);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseDate(dueDate);
        ZonedDateTime paid = ZonedDateTime.parse(paidAt, INSTANT_FMT).withZoneSameInstant(WARSAW);
        long diff = ChronoUnit.DAYS.between(due, paid.toLocalDate());
        return (int) Math.max(0, diff);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseDate(date);
        LocalDate result = start.plusMonths(months);
        if (start.getDayOfMonth() == start.lengthOfMonth()) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        } else if (result.getDayOfMonth() < start.getDayOfMonth()) {
            result = result.withDayOfMonth(Math.min(start.getDayOfMonth(), result.lengthOfMonth()));
        }
        return result.format(DATE_FMT);
    }

    private LocalDate parseDate(String date) {
        try {
            return LocalDate.parse(date, DATE_FMT);
        } catch (DateTimeParseException | NullPointerException e) {
            throw new IllegalArgumentException("Invalid date: " + date);
        }
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !HOLIDAYS.contains(MonthDay.from(date));
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate next = date.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }
}
